head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15101";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15101.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "a_28", attr: "src", fn: function () { return "mailto:" + String(dma_officialDocument.get("wrtrEmail")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_39", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP'); } }, { id: "txt_text40", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP'); } }, { id: "img_42", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS'); } }, { id: "txt_text43", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS'); } }, { id: "img_45", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC'); } }, { id: "txt_text46", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC'); } }, { id: "img_48", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT'); } }, { id: "txt_text49", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT'); } }, { id: "img_51", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'); } }, { id: "txt_text52", fn: function(){ return ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_53", fn: function(){ return (!(((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP') || ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS') || ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC') || ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT') || ((dlt_officialDocumentBbsAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'))); } }, { id: "c_when_68", fn: function(){ return (!(String(((dma_officialDocument.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO"); })())) === null ? '' : ((dma_officialDocument.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO"); })()))).length === 0)); } }, { id: "c_otherwise_72", fn: function(){ return (!((!(String(((dma_officialDocument.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO"); })())) === null ? '' : ((dma_officialDocument.get("nextBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO"); })()))).length === 0)))); } }, { id: "c_when_80", fn: function(){ return (!(String(((dma_officialDocument.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO"); })())) === null ? '' : ((dma_officialDocument.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO"); })()))).length === 0)); } }, { id: "c_otherwise_84", fn: function(){ return (!((!(String(((dma_officialDocument.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO"); })())) === null ? '' : ((dma_officialDocument.get("preBbsVO") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO"); })()))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_35", entity: "dlt_officialDocumentBbsAttachVO", countIds: [], cells: [{ childId: "__rc4", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc5", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc6", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc9", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "a_28", fn: function () { return String(dma_officialDocument.get("wrtrEmail")); } },
        { childId: "__rb3", fn: function () { return String(String(String(dma_officialDocument.get("contnContn")) === null ? '' : String(dma_officialDocument.get("contnContn"))).split(String.fromCharCode(10)).join('<br/>')); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldfil15101: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e){
    try {
        await scwin.fileDown('' + dma_officialDocument.get("contnId") + '','' + dlt_officialDocumentBbsAttachVO.getCellData(0, "contnAttachSeq") + '','' + dlt_officialDocumentBbsAttachVO.getCellData(0, "attachFileNm") + '','' + dma_officialDocument.get("wrtDdtm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15101.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_onclick
 * @description btn_GoURL 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_onclick = async function(e){
    try {
        await scwin.goURL('list')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15101.btn_GoURL_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_2_onclick
 * @description 「${officialDocument.nextBbsVO.title}」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_2_onclick = async function(e){
    try {
        await scwin.goURL('detail',(String(((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO.contnId"); })())) === null ? '' : ((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO.contnId"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO.contnId"); })())) === null ? '' : ((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.nextBbsVO.contnId"); })())))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15101.btn_GoURL_2_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_3_onclick
 * @description 「${officialDocument.preBbsVO.title}」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_3_onclick = async function(e){
    try {
        await scwin.goURL('detail',(String(((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO.contnId"); })())) === null ? '' : ((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO.contnId"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO.contnId"); })())) === null ? '' : ((dma_officialDocument.get("contnId") ?? (() => { throw new Error("unresolved:" + "officialDocument.preBbsVO.contnId"); })())))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15101.btn_GoURL_3_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_GoURL
 * @description Go URL 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoURL = async function () {
    const sbmOptions = {
        id: "tx_fn_GoURL",
        method: "post",
        action: "/support/officialDocument.do",
        ref: "dma_GoURLReq",
        target: "dlt_officialDocumentBbsAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/support/fileDownload.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {String} flag flag
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goURL = async function (flag, contnId) {
    if (flag === 'list') {
        $c.util.getComponent('dma_GoURLReq').set('method', 'searchOfficialDocument');
        (document.officialDocumentForm || { elements: [] }).action = 'officialDocument.do';
        { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15100/jldfil15100.xml", { "method": 'searchOfficialDocument', "contnId": contnId }); } };
    } else {
        if (flag === 'detail') {
            $c.util.getComponent('dma_GoURLReq').set('method', 'searchOfficialDocumentDetail');
            $c.util.getComponent('dma_GoURLReq').set('contnId', contnId);
            (document.officialDocumentForm || { elements: [] }).action = 'officialDocument.do';
            { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15100/jldfil15100.xml", { "method": 'searchOfficialDocument', "contnId": contnId }); } };
        }
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} contnId contnId
 * @param {*} attachSeq attachSeq
 * @param {String} attachFileNm attachFileNm
 * @param {*} wrtDdtm wrtDdtm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (contnId, attachSeq, attachFileNm, wrtDdtm) {
    $c.util.getComponent('dma_GoURLReq').set('method', 'searchBbsAttachFile');
    $c.util.getComponent('dma_GoURLReq').set('contnId', contnId);
    $c.util.getComponent('dma_GoURLReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_GoURLReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_GoURLReq').set('wrtDdtm', wrtDdtm);
    (document.officialDocumentForm || { elements: [] }).action = '/support/fileDownload.do';
    await scwin.tx_fn_FileDown();
};
